  "srRejection": "Rejeição (oferta)",
  "srHowTitle": "Como identificá-los",
  "srHowBody": "O suporte é um nível onde o preço deixa de cair e ressalta: a procura supera a oferta.\nA resistência é um nível onde o preço deixa de subir e se vira: a oferta supera a procura.\nQuantos mais ressaltos ou rejeições um nível acumula, mais fiável é.\nSe o preço rompe o nível com força e volume, suporte e resistência trocam de papel.",
  "srUseTitle": "Uso prático",
  "srUseBody": "Procurar compras perto do suporte, com o stop mesmo por baixo.\nRealizar lucros ou vender perto da resistência.\nOperar a rutura apenas quando se confirma, idealmente com o reteste do nível.",
