  "brkNote": "Regra de ouro: estes travões existem para os dias maus, que são precisamente quando menos vontade terá de os respeitar. Escreva-os e tenha-os à vista.",
  "pckTitle": "Checklist pré-operação",
  "pckIntro": "Antes de carregar em 'comprar', marque o que se cumpre. Quantas mais caixas, melhor a operação; se ficarem muitas por marcar, salte: haverá sempre outra.",
