  "rdyTitle": "Está em condições de operar hoje?",
  "rdyIntro": "Um minuto de honestidade antes da sessão. Responda e veja o seu estado: o mercado continuará lá amanhã; a sua conta talvez não, se operar em má altura.",
  "rdyQ1": "Dormi e descansei bem",
