  "rdyReset": "Reiniciar",
  "tviTitle": "O paradoxo: tempo vs impacto",
  "tviIntro": "A maior parte do seu tempo vai-se em analisar, mas a maior parte do resultado depende da psicologia e da gestão do risco. Está a investir as suas horas quase ao contrário do que realmente move a sua rentabilidade.",
  "tviTimeLabel": "Tempo que lhe dedica",
  "tviImpactLabel": "Impacto no resultado",
  "tviTimeShort": "Tempo",
  "tviImpactShort": "Impacto",
  "tviCat1Name": "Análise e estratégia",
  "tviCat1Note": "gráficos, indicadores, backtesting, procurar o setup perfeito",
