  "tviCat3Name": "Psicologia e disciplina",
  "tviCat3Note": "seguir o plano, controlar o medo e a ganância, não operar por impulso",
  "tviRoiLabel": "rende por hora",
  "tviTakeaway": "«O êxito no trading é 10% estratégia, 30% gestão do dinheiro e 60% psicologia.» — atribuído a Van K. Tharp. Cada hora que dedica à sua mente e ao seu risco rende muito mais do que outra hora à procura do indicador perfeito.",
  "tviAction": "O que fazer com isto: não largue a análise, mas reequilibre. Dedique tempo deliberado ao que mais rende: um plano escrito, regras de risco fixas (1% por operação), um diário para rever os seus erros emocionais e uma rotina que o trave quando está em brasa.",
  "tviDisclaimer": "As percentagens de impacto seguem a ponderação clássica de Van K. Tharp (60/30/10); outros autores (Douglas, Steenbarger) dão números parecidos (psicologia 60-80%). As percentagens de tempo são ilustrativas de uma repartição típica, não um dado de estudo.",
  "shTitle": "Comece aqui",
  "shIntro": "Se é a sua primeira vez, este é o único módulo de que precisa para começar. Em 9 passos verá do que se trata realmente abrir uma operação: o que significa comprar ou vender, como ler o gráfico, quanto arriscar e como colocar e fechar a sua primeira ordem. Sem fumo: só o que vai mesmo usar no primeiro dia.",
