  "structLogClear": "Limpar",
  "structLogNote": "O scanner recorda o que deteta neste ativo (ruturas de estrutura e sinais de velas) e conserva-o aqui mesmo que recarregue a página. O que está realçado a azul foi visto pela primeira vez nas últimas 24h.",
