  "nasdaqMode": "Nasdaq",
  "ideskTitle": "A mesa institucional",
  "ideskIntro": "Um banco ou fundo não «faz trading» como o retalho: reparte o trabalho por especialistas, com processos, limites e tecnologia. Aqui vê como funciona uma mesa profissional por dentro e o que pode roubar de cada função para operar como um profissional mesmo estando sozinho em casa.",
  "discTitle": "Disciplina e desempenho profissional",
  "discIntro": "O que separa o profissional rentável do retalho que se queima não é o indicador secreto: é como gerem a sua mente, os seus erros e o seu stress sob pressão. Este é o «software» do trader de elite, emprestado de mesas institucionais, pilotos, cirurgiões e desportistas de alto rendimento.",
  "mstTitle": "Stress test de margem",
  "mstIntro": "Antes de abrir uma posição alavancada, verifique se sobrevive a uma queda forte. Introduza o seu saldo e as suas posições e verá, cenário a cenário, quanto perde, quanto saldo lhe fica e se dispara a margin call ou a liquidação. A pergunta-chave: \"aguento um −20 %?\".",
  "mstAccount": "Saldo da conta",
  "mstMaintRate": "Margem de manutenção",
  "mstPosition": "Posição",
  "mstLong": "Longo",
  "mstShort": "Curto",
  "mstAddPosition": "Adicionar posição",
  "mstGross": "Exposição bruta",
  "mstNet": "Exposição líquida",
  "mstLeverage": "Alavancagem",
  "mstNeutral": "Carteira neutra (longos e curtos compensam-se): sem um movimento direcional puro que dispare a liquidação. Atenção ao risco de base.",
  "mstLiqLabel": "É liquidado com um movimento de mercado de",
  "mstLiqSub": "aplicado à sua exposição líquida (negativo = queda; positivo = subida)",
  "mstScenariosTitle": "Cenários de mercado",
  "mstColMove": "Movimento",
  "mstColPnl": "P&L",
  "mstColEquity": "Saldo após o golpe",
  "mstColStatus": "Estado",
  "mstOk": "Aguenta",
  "mstCall": "Margin call",
  "mstLiq": "Liquidado",
  "mstCustom": "Cenário personalizado",
  "mstNote": "Modelo simplificado: uma corretora real faz netting por produto e aplica uma margem de manutenção diferente consoante o ativo (cripto ~0,5 %, CFD de índices/forex mais alta). Use-o para ver a ORDEM DE GRANDEZA do risco, não como número exato da sua corretora. Lição: quanto maior a alavancagem, mais perto está a liquidação de um movimento normal de mercado.",
  "edgeUseJournal": "Usar os meus dados do diário",
  "edgeLoaded": "Carregado a partir de {n} operações reais do seu diário",
  "edgeNoData": "Ainda não tem operações fechadas no diário. Registe algumas e volte.",
  "edgeNotLogged": "Inicie sessão e registe operações no diário para usar os seus dados reais.",
  "edgeSampleWarn": "amostra pequena, fiabilidade limitada (ideal ≥100 operações)",
  "tvSearchAsset": "Procurar ativo…",
  "alertSymbolPh": "BTC, AAPL…",
  "ddrTitle": "Drawdown e recuperação",
  "ddrIntro": "A matemática do drawdown é assimétrica e cruel: perder 50% exige ganhar 100% só para voltar ao ponto de partida. Esta calculadora mostra-lhe quanto precisa de recuperar e quantas operações lhe custará com o seu expectancy atual — a razão pela qual os fundos profissionais cortam o tamanho assim que o drawdown ultrapassa o seu limite (normalmente 10-20%).",
  "ddrDrawdown": "Drawdown atual",
  "ddrExpectancy": "Expectancy por operação",
  "ddrRequired": "Ganho necessário para recuperar",
  "ddrRequiredSub": "sobre o capital restante, só para voltar ao break-even",
  "ddrTrades": "Operações estimadas",
  "ddrTradesSub": "com o seu risco e expectancy atuais, em composto (∞ = sem vantagem nunca se recupera)",
  "ddrTableTitle": "Tabela: perda → ganho necessário",
  "ddrColDd": "Drawdown",
  "ddrColReq": "Recuperação necessária",
  "ddrNote": "Política institucional: os fundos definem um drawdown máximo aceitável (p. ex. 15-20%) e regras automáticas — a -10% reduz-se o tamanho para metade, a -15% para-se de operar e revê-se o sistema. Um VaR (valor em risco) diário limita quanto a mesa pode perder num dia normal. Copie a ideia: defina O SEU limite antes de operar, não durante a queda.",
  "heatCorrLabel": "Correlação média entre posições",
  "heatEffective": "Risco efetivo ajustado",
  "heatEffectiveSub": "entre diversificação total (0%) e uma só grande operação (100%). Vários pares USD ou várias tecnológicas ≈ 60-90%.",
  "gkTitle": "Gregas de opções",
  "gkIntro": "As gregas medem como muda o preço de uma opção quando se move cada variável: subjacente, tempo, volatilidade e taxas. São o painel de instrumentos do trader de opções — sem elas voa às cegas. Cada cartão inclui um exemplo numérico; pratique depois com a calculadora Black-Scholes da secção Opções.",
  "mlqTitle": "Margem e liquidação em derivados",
  "mlqIntro": "Se opera futuros ou perpétuos com alavancagem, a margem é a sua vida. A maioria das contas não morre por uma má análise, mas por não perceber COMO e QUANDO a exchange o liquida. Este módulo explica os modos de margem, os modos de posição, o preço de liquidação e como se proteger dos pavios de manipulação.",
  "ntTitle": "Operar notícias e eventos",
  "ntIntro": "Os dados de alto impacto (NFP, IPC, taxas) movem o mercado em segundos. Saber o que fazer antes, durante e depois separa uma oportunidade de uma conta queimada. Use o calendário económico do Dashboard para saber quando chegam.",
  "smTitle": "Sentimento de mercado",
  "smIntro": "Mede o que a massa sente: medo ou ganância. Nos extremos, o sentimento é combustível contrarian — quando TODOS estão comprados já não há ninguém para comprar. Complementa o COT (posicionamento real) que já tem neste pilar.",
  "imTitle": "Análise intermercado",
  "imIntro": "Nenhum mercado se move sozinho (John Murphy). Dólar, obrigações, matérias-primas e bolsa estão ligados: ler essas relações dá-lhe o contexto macro que confirma —ou desmente— a sua operação. É 15% do exame CMT por alguma razão.",
  "bcTitle": "Amplitude, ciclos e sazonalidade",
  "bcIntro": "Um índice pode subir sustentado por 5 valores gigantes enquanto o resto afunda: a amplitude mede a saúde INTERNA do movimento. Os ciclos e a sazonalidade acrescentam o 'quando' estatístico. Matéria de exame CMT que quase nenhum retalhista olha.",
  "bkrTitle": "Corretoras, regulação e burlas",
  "bkrIntro": "Pode fazer tudo bem no gráfico e perder tudo escolhendo mal onde deposita. Este módulo ensina-o a verificar uma corretora em 10 minutos e a reconhecer as burlas que arrasam este setor.",
  "cmpCalcTitle": "Juros compostos",
