  "rorTitle": "Risco de ruína",
  "rorIntro": "A probabilidade de a sua conta atingir uma determinada queda em 500 operações, segundo a sua vantagem e o tamanho da aposta. Monte Carlo sobre 5.000 simulações com tamanho fracional fixo.",
