  "rorVerdictNegative": "Expectativa negativa: com estes números a ruína não é um risco, é uma certeza matemática a longo prazo. Antes de ajustar o risco, precisa de um sistema com vantagem.",
  "rorVerdictHigh": "Sistema com vantagem, mas o risco por operação é demasiado alto: a probabilidade de ruína continua séria. Baixe a % por operação e veja como se desmorona.",
  "rorVerdictOk": "Combinação sólida: vantagem positiva e risco controlado. Lembre-se de que a simulação assume disciplina perfeita — o stop respeita-se sempre.",
  "rorRecoveryTitle": "A matemática da recuperação: o que perde vs. o que precisa de ganhar",
