  "advTaTitle": "Técnica avançada",
  "advTaIntro": "Ferramentas baseadas em volume e conceitos dedicados que complementam a análise técnica de base: onde o volume foi realmente negociado e o que cada vela esconde.",
  "tbizTitle": "O negócio do trading",
  "tbizIntro": "O que rodeia a operativa e quase ninguém ensina: como financiar-se, cumprir com o Fisco e fazer crescer a conta de forma sustentável.",
  "killerTagPsych": "Psicologia",
