  "testimonial1Quote_l010": "Passei de operar às cegas a ter métricas claras de R/R, tamanho de posição e win rate. A minha conta já não sofre drawdowns brutais.",
  "testimonial1Author_l011": "Carlos M.",
  "testimonial1Role_l012": "Day Trader Cripto · 4 anos",
  "testimonial2Quote_l020": "O Strategy Optimizer e o AI Coach poupam-me horas de análise. Justifico o custo todos os meses com uma só operação bem planeada.",
  "testimonial2Author_l021": "Ana R.",
  "testimonial2Role_l022": "Swing Trader de Opções",
  "testimonial3Quote_l030": "Uso-o diariamente há 8 meses. O Monte Carlo e o diário mudaram a minha forma de ver o risco. 5 estrelas.",
  "testimonial3Author_l031": "David L.",
  "testimonial3Role_l032": "Trader Independente · Forex",
  "faqQ1_l040": "Preciso de ser especialista para o usar?",
  "faqA1_l041": "Não. A aplicação guia-o passo a passo em cada calculadora e o Centro de Aprendizagem cobre desde o básico (o que é um Stop Loss) até estratégias avançadas com opções. Há um Demo Trader gratuito para experimentar tudo sem risco.",
  "faqQ2_l050": "Posso cancelar a subscrição quando quiser?",
  "faqA2_l051": "Sim. Cancele com 1 clique a partir do seu perfil. Não há fidelização. Se comprar o plano Vitalício, o acesso é permanente — sem pagamentos recorrentes.",
  "faqQ3_l060": "Que ativos são suportados?",
  "faqA3_l061": "Cripto, Forex, Ações dos EUA (NYSE/NASDAQ), Índices (SPX, NDX, DAX, etc.), Matérias-Primas e Futuros. Os dados de cripto são em tempo real; os restantes podem ter atraso.",
  "faqQ4_l070": "A IA do Trade Coach paga-se à parte?",
  "faqA4_l071": "Não. O AI Trade Coach (Claude Sonnet 4.5) está incluído em todos os planos Premium. Analisa a sua estratégia, identifica riscos e sugere melhorias como um mentor sénior.",
  "faqQ5_l080": "Funciona no telemóvel?",
  "faqA5_l081": "Sim. Design totalmente responsivo. As calculadoras e o dashboard funcionam perfeitamente em iOS/Android. App nativa no roadmap do Q2.",
