  "smcTitle": "Smart Money / ICT",
  "optTitle": "Estratégias de opções",
  "optIntro": "Combinar calls e puts permite-lhe construir posições com risco definido e tirar partido não só da direção, mas também da volatilidade e da passagem do tempo. Use a Calculadora de Opções para ver as gregas e o diagrama de payoff de cada uma.",
  "smcIntro": "A abordagem 'smart money' (popularizada pelo ICT) tenta seguir o rasto do dinheiro institucional: onde acumulam ordens, como caçam a liquidez do retalho e para onde o preço regressa. É discricionária: use-a como confluência, não como sistema mágico.",
  "ichiIntro": "Um 'gráfico de equilíbrio num relance' japonês, criado por Goichi Hosoda. Cinco linhas e uma 'nuvem' projetada mostram ao mesmo tempo a tendência, o suporte/resistência, o momentum e os sinais de entrada: foi concebido para ler o mercado num só olhar. Muito popular em forex e cripto.",
  "ewTitle": "Teoria das Ondas de Elliott",
  "ewIntro": "Ralph Elliott observou que a psicologia das massas move os mercados em padrões de ondas repetitivos. O preço avança numa sequência 'motriz' de 5 ondas na direção da tendência e depois corrige numa sequência de 3 ondas em sentido contrário. A mesma forma 5-3 repete-se em cada grau, de minutos a décadas.",
