  "cmtPosSizeTitle": "Calculadora de Tamanho de Posição",
  "cmtPosSizeIntro": "Converte um risco fixo em % no tamanho exato da posição a partir da sua entrada e do seu stop. É o número mais importante da gestão de risco: dimensione a partir do stop, nunca a partir de um lote redondo.",
