  "cmtKellyTitle": "Calculadora do Critério de Kelly",
  "cmtKellyIntro": "A fração de Kelly é a % de capital matematicamente ótima a arriscar segundo a sua vantagem. O Kelly completo maximiza o crescimento a longo prazo mas é brutalmente volátil: os profissionais usam uma fração.",
  "cmtWinRate": "Taxa de Acerto (%)",
