  "cmpTradesLow": "Baixa",
  "cmpFooter": "Mais tempo de ecrã e mais stress não é 'mais profissional': muitos traders consistentemente rentáveis são de swing ou de posição e olham para os gráficos uma vez por dia.",
  "rorRiskPct": "Risco por operação",
