  "rorResultSub": "probabilidade de atingir essa queda",
  "heatTitle": "Calor da carteira",
  "heatIntro": "O seu risco aberto total: o que perderia se todas as suas posições abertas tocassem no stop ao mesmo tempo. Limite isto, não só o risco por operação.",
  "heatPosition": "Posição",
  "heatAddPosition": "Adicionar posição",
  "heatTotal": "Calor total",
  "heatOk": "Saudável. A exposição total está controlada mesmo num dia mau.",
  "heatWarn": "A subir. Um conjunto de stops correlacionados pode doer; considere cortar.",
  "heatDanger": "Demasiado alto. Uma má sessão pode provocar uma queda séria. Reduza o tamanho ou feche posições.",
  "heatCorrelationNote": "As posições correlacionadas (p. ex. vários pares com USD, ou ações tecnológicas) funcionam como uma só operação grande: o seu risco combinado real é maior do que a soma aqui mostrada.",
  "streakTitle": "Probabilidade de séries perdedoras",
  "streakIntro": "Mesmo um grande sistema tem séries perdedoras longas. Esta é a probabilidade exata de uma série de perdas consecutivas na sua amostra, para que não o apanhem de surpresa.",
  "streakTrades": "Número de operações",
  "streakExpLongest": "Série mais longa esperada",
  "streakExpLongestSub": "pior série típica nesta amostra",
  "streakLosses": "perdas",
  "streakTableTitle": "Probabilidade de uma série de pelo menos…",
  "streakColLength": "Comprimento da série",
  "streakColProb": "Probabilidade",
  "streakNote": "Um sistema de 50% em 100 operações terá quase de certeza uma série de 6-7 perdas. Dimensione para que uma série normal nunca ameace a sua conta.",
  "capitalAdvancedToolsTitle": "Análise avançada de risco",
  "wyckoffSchematicTitle": "Esquemas de Wyckoff",
  "wyckoffSchematicIntro": "A anatomia clássica de um range de acumulação e de um de distribuição, evento a evento, com as fases A-E.",
  "wyckoffAccSchematic": "Acumulação (depois subida)",
  "wyckoffDistSchematic": "Distribuição (depois descida)",
  "wyckoffReaccName": "Reacumulação",
  "wyckoffReaccDesc": "Uma pausa dentro de uma tendência de alta: o preço consolida, sacode as mãos fracas e retoma a subida. Mesma estrutura da acumulação, mas dentro de uma tendência de alta.",
  "wyckoffRedistName": "Redistribuição",
  "wyckoffRedistDesc": "Uma pausa dentro de uma tendência de baixa: o preço consolida, apanha os compradores de rutura e continua a cair. Mesma estrutura da distribuição, mas dentro de uma tendência de baixa.",
  "wyckoffLPSName": "LPS — Último ponto de suporte",
