  "cotTitle": "Relatório COT",
  "cotIntro": "O relatório de Compromissos dos Operadores (COT), publicado semanalmente pela CFTC dos EUA, mostra como estão realmente posicionados os maiores participantes nos mercados de futuros. É o mais próximo que o trader de retalho tem de ver a mão do dinheiro institucional.",
  "cotVisualTitle": "Ler o posicionamento",
