  "strat_csp_desc": "Vende uma put reservando em dinheiro 100% do strike. Mesmo payoff da short put, capital imobilizado diferente.",
  "strat_protective_put_desc": "Ações mais uma put comprada por baixo: um seguro com franquia.",
  "strat_covered_put_desc": "Ações vendidas a descoberto mais uma put vendida. Recebe prémio enquanto o preço não subir.",
  "strat_covered_strangle_desc": "Ações mais uma call e uma put vendidas fora do dinheiro. Prémio duplo, obrigação de ambos os lados.",
  "strat_ratio_call_write_desc": "Ações com duas calls vendidas: uma coberta e outra a descoberto.",
  "strat_ratio_put_write_desc": "Curto em ações com duas puts vendidas: uma coberta e outra a descoberto.",
  "strat_stock_repair_desc": "Sobre ações em perda: uma call comprada e duas vendidas mais acima para baixar o ponto de equilíbrio sem pôr mais dinheiro.",
  "strat_call_calendar_desc": "Vende a call próxima e compra a mesma call num vencimento posterior. Vive de o tempo correr mais depressa na curta.",
  "strat_put_calendar_desc": "Vende a put próxima e compra a mesma put mais longe no tempo.",
  "strat_call_diagonal_desc": "Calendar com strikes diferentes: a curta mais acima acrescenta viés de alta ao recebimento de tempo.",
  "strat_put_diagonal_desc": "Calendar de puts com strikes diferentes: a curta mais abaixo acrescenta viés de baixa.",
  "strat_double_calendar_desc": "Dois calendars, um com puts por baixo e outro com calls por cima. Ganha se o preço acabar entre ambos.",
  "strat_double_diagonal_desc": "Duplo calendar com as pernas longas mais afastadas: alarga a zona de lucro à custa de mais débito.",
  "strat_jelly_roll_desc": "A diferença entre dois sintéticos do mesmo strike em dois vencimentos. O seu preço é pura taxa de juro e dividendo.",
  "strat_pmcc_desc": "Uma call muito dentro do dinheiro e de longo prazo faz de ações, e contra ela vende-se uma call próxima. A covered call sem comprar as 100 ações.",
  "strat_zebra_desc": "Duas calls dentro do dinheiro compradas contra uma vendida: delta ~100 sem valor extrínseco líquido.",
  "strat_risk_reversal_desc": "Financia a call comprada vendendo uma put. Sintético de alta a custo quase zero.",
  "strat_seagull_desc": "Risk reversal com a subida limitada por uma call vendida mais acima: baratea a estrutura abdicando do troço final.",
  "strat_big_lizard_desc": "Straddle vendido com uma call comprada por cima: elimina o risco na subida e deixa só o de baixo.",
  "strat_reverse_jade_desc": "Call vendida mais spread de puts vendido: sem risco por baixo, com ele por cima.",
  "strat_long_call_condor_desc": "Quatro calls que definem um planalto de lucro entre os dois strikes centrais.",
  "strat_long_put_condor_desc": "O mesmo condor construído inteiramente com puts.",
  "strat_long_put_butterfly_desc": "Borboleta de puts: máximo no strike central, risco limitado ao débito.",
  "strat_put_bwb_desc": "Borboleta de puts com uma asa mais larga do que a outra. Costuma abrir-se a crédito e transfere todo o risco para um só lado.",
  "strat_xmas_call_desc": "Borboleta assimétrica de calls na proporção 1-3-2: mais barata do que a borboleta clássica, com a zona de lucro deslocada.",
  "strat_xmas_put_desc": "A versão com puts da borboleta 1-3-2, deslocada para baixo.",
  "strat_bull_call_ladder_desc": "Bull call spread com uma terceira call vendida mais acima. O crédito extra abre risco ilimitado por cima.",
  "strat_bear_call_ladder_desc": "Call vendida em baixo e duas compradas em cima: perde no range e ganha se o movimento de subida for grande.",
