  "helpContractSize": "Cada futuro representa uma quantidade fixa do subjacente, e não é a mesma em todos. Um contrato do E-mini S&P move 50 $ por ponto; um de crude, 1.000 barris. Esse multiplicador é o que transforma um movimento pequeno num resultado grande.",
